#!/usr/bin/env python3
"""Cache watchdog: invalidação reativa do siz_cache.sqlite via inotify + polling."""
from __future__ import annotations
import hashlib
import os
import sqlite3
import threading
import time
from pathlib import Path

CACHE_DB = Path(os.environ.get("SIZ_CACHE_DIR", "/mnt/dados/harness/cache")) / "siz_cache.sqlite"
POLL_INTERVAL = int(os.environ.get("WATCHDOG_POLL_INTERVAL", "30"))
IGNORE_PATTERNS = frozenset({".git", "node_modules", "__pycache__", ".venv", "venv"})


def _should_ignore(path: Path) -> bool:
    return any(part in IGNORE_PATTERNS for part in path.parts)


def _invalidate_file(db_path: Path, file_path: str) -> None:
    try:
        con = sqlite3.connect(str(db_path), timeout=3)
        con.execute("DELETE FROM siz_ast WHERE path = ?", (file_path,))
        con.commit()
        con.close()
    except sqlite3.Error:
        pass


def _invalidate_all(db_path: Path) -> None:
    try:
        con = sqlite3.connect(str(db_path), timeout=3)
        con.execute("DELETE FROM siz_ast")
        con.commit()
        con.close()
    except sqlite3.Error:
        pass


def _compute_fingerprint(path: Path) -> str | None:
    try:
        st = path.stat()
        return f"{st.st_mtime_ns}:{st.st_size}"
    except OSError:
        return None


class CacheWatchdog:
    def __init__(self, watch_dirs: list[Path], db_path: Path = CACHE_DB,
                 poll_interval: int = POLL_INTERVAL):
        self.watch_dirs = [Path(d) for d in watch_dirs]
        self.db_path = db_path
        self.poll_interval = poll_interval
        self._fingerprints: dict[str, str] = {}
        self._running = False
        self._thread: threading.Thread | None = None
        self._inotify_available = False
        try:
            import inotify.adapters
            self._inotify_available = True
        except ImportError:
            pass

    def _snapshot_fingerprints(self) -> dict[str, str]:
        snap = {}
        for watch_dir in self.watch_dirs:
            if not watch_dir.exists():
                continue
            for fp in watch_dir.rglob("*"):
                if fp.is_file() and not _should_ignore(fp):
                    fp_str = str(fp)
                    fp_hash = _compute_fingerprint(fp)
                    if fp_hash:
                        snap[fp_str] = fp_hash
        return snap

    def _poll_cycle(self) -> None:
        current = self._snapshot_fingerprints()
        for fp_str, fp_hash in current.items():
            old_hash = self._fingerprints.get(fp_str)
            if old_hash != fp_hash:
                _invalidate_file(self.db_path, fp_str)
        removed = set(self._fingerprints.keys()) - set(current.keys())
        for fp_str in removed:
            _invalidate_file(self.db_path, fp_str)
        self._fingerprints = current

    def _run_poll(self) -> None:
        self._fingerprints = self._snapshot_fingerprints()
        while self._running:
            time.sleep(self.poll_interval)
            self._poll_cycle()

    def _run_inotify(self) -> None:
        import inotify.adapters
        i = inotify.adapters.Inotify()
        for watch_dir in self.watch_dirs:
            if watch_dir.exists():
                i.add_watch(str(watch_dir), recursive=True)
        for event in i.event_gen(yield_nones=False):
            if not self._running:
                break
            (_, type_flags, path, filename) = event
            if filename and _should_ignore(Path(filename)):
                continue
            if any(f in type_flags for f in ["IN_MODIFY", "IN_CREATE", "IN_DELETE"]):
                full_path = Path(path) / filename if filename else Path(path)
                _invalidate_file(self.db_path, str(full_path))

    def start(self) -> None:
        if self._running:
            return
        self._running = True
        if self._inotify_available:
            self._thread = threading.Thread(target=self._run_inotify, daemon=True)
        else:
            self._thread = threading.Thread(target=self._run_poll, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._running = False
        if self._thread:
            self._thread.join(timeout=5)
            self._thread = None


if __name__ == "__main__":
    import sys
    dirs = [Path(d) for d in sys.argv[1:]] or [Path(".")]
    dog = CacheWatchdog(dirs)
    dog.start()
    print(f"CacheWatchdog started: watching {len(dirs)} dirs, poll={POLL_INTERVAL}s, inotify={dog._inotify_available}")
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        dog.stop()
        print("CacheWatchdog stopped.")

