                _invalidate_file(self.db_path, str(full_path))

    def start(self) -> None:
        if self._running:
            return
        self._running = True
        if self._inotify_available:
            self._thread = threading.Thread(target=self._run_inotify, daemon=True)
        else:
            self._thread = threading.Thread(target=self._run_poll, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._running = False
        if self._thread:
            self._thread.join(timeout=5)
            self._thread = None


